/// 字符的位图行（16 行，位 15 是最左像素）。
pub(super) fn glyph_rows(c: char) -> Option<(&'static [u16; 16], u32)> {
    if let Some(i) = (c as u32).checked_sub(32).filter(|i| *i < 95) {
        return Some((&ASCII[i as usize], ASC_W));
    }
    CJK_CHARS.iter().position(|&x| x == c).map(|i| (&CJK[i], CJK_W))
}

/// 字符前进宽度。
pub(super) fn advance(c: char) -> u32 {
    if (c as u32) < 128 { ASC_W } else { CJK_W }
}

/// 一段文字的像素宽度。
pub(super) fn text_width(s: &str) -> u32 {
    s.chars().map(advance).sum()
}
